    procs[n]=subprocess.Popen(cmd,shell=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
libs={}
for n,p in procs.items():
    try: out,_=p.communicate(timeout=max(1,80-(time.time()-t0)))
    except subprocess.TimeoutExpired: p.kill(); out="TIMEOUT"
    print(n, p.returncode, round(time.time()-t0,1))
    if p.returncode==0: libs[n]=ctypes.CDLL(f"/tmp/oproj/{n}.so")
    else:
        ls=[l for l in out.splitlines() if "error" in l][:3]; print("\n".join(l[:300] for l in ls))
N=K=2560
W=torch.randn(N,K,device="cuda").bfloat16()
for n,l in libs.items():
    l.launch.argtypes=[ctypes.c_void_p]*4+[ctypes.c_int]*3+[ctypes.c_void_p]+[ctypes.c_int]*3+[ctypes.c_void_p]
    l.ws_size.restype=ctypes.c_size_t
    print(n,"smem",l.smem())
res={}
for M in [2048,4096,4106,7976,8192]:
    A=torch.randn(M,K,device="cuda").bfloat16(); R=torch.randn(M,N,device="cuda").bfloat16(); D=torch.empty(M,N,device="cuda",dtype=torch.bfloat16)
    ref=(A.float()@W.float().t()+R.float())
    row=[]
    for n,l in libs.items():
        mode=0
        ws=torch.empty(max(1,l.ws_size(M,N,K,mode)),dtype=torch.uint8,device="cuda")
        s=torch.cuda.current_stream().cuda_stream
        def fn(A,R,W,D,l=l,ws=ws):
            rc=l.launch(A.data_ptr(),R.data_ptr(),W.data_ptr(),D.data_ptr(),A.shape[0],N,K,ws.data_ptr(),0,1,mode,torch.cuda.current_stream().cuda_stream)
            assert rc==0, rc
        D.zero_(); fn(A,R,W,D); torch.cuda.synchronize()
        err=(D.float()-ref).abs().max().item()
        t=b200probe.harness_time(fn,(A,R,W),(D,))
        row.append(f"{n}:{t:.1f}us(err{err:.2f},ws{ws.numel()})")
    print(M, " ".join(row), round(time.time()-t0,1))

