cublasLtHandle_t get_handle() {
    static cublasLtHandle_t h = nullptr;
    static std::once_flag once;
    std::call_once(once, [] { cublasLtCreate(&h); });
    return h;
}

int sm_count() {
    static int n = 0;
    static std::once_flag once;
    std::call_once(once, [] {
        int dev = 0;
        cudaGetDevice(&dev);
        cudaDeviceGetAttribute(&n, cudaDevAttrMultiProcessorCount, dev);
    });
    return n;
}

